import sqlite3
import json
import requests
import sys

def load_config():
    with open('config.json') as f:
        return json.load(f)

def get_db_connection():
    return sqlite3.connect('users.db')

def process_username(username):
    config = load_config()
    api_url = config['api_url']
    api_token = config['api_token']

    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute("SELECT allowed FROM users WHERE username = ?", (username,))
    result = cursor.fetchone()
    conn.close()

    if result is None:
        print(f"missing {username}")
        return

    allowed = result[0]
    if allowed == 0:
        print(f"skipped {username}")
        return

    email = None
    cursor = conn.cursor()
    cursor.execute("SELECT email FROM users WHERE username = ?", (username,))
    email = cursor.fetchone()[0]
    cursor.close()

    try:
        response = requests.post(
            f"{api_url}/notify",
            json={"email": email, "message": "Hello"},
            headers={"Authorization": f"Bearer {api_token}"}
        )
        print(f"{response.status_code} {response.text}")
    except requests.RequestException as e:
        print(f"error sending notification for {username}")

if __name__ == "__main__":
    for username in sys.stdin:
        username = username.strip()
        if username:
            process_username(username)
